      "key": "foundation_selection",
      "label": "Capability and foundation selection"
    },
    {
      "conditions": [],
      "definition": "Entity lifecycle completeness concerns domain entities and independently governed value families, using a matrix or equivalent closed representation of Entity, Identity, Authority owner, Declare/create, Read/project, Update/transition and Delete/retire. It is distinct from operational module lifecycle confirmation concerning build, release, deployment, observation and retirement.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 750,
          "quote": "For each entity, design evidence must provide this logical-completeness matrix\nor an equivalent closed representation:\n\n| Entity | Identity | Authority owner | Declare/create | Read/project | Update/transition | Delete/retire |",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/DESIGN_MODULE_METHOD.md#Design%20Module%20Method%2F4B.%20Ontology-First%20Design%20Rule%2FEntity%20And%20Lifecycle%20Completeness",
