      "exceptions": [],
      "grounding": [
        {
          "end_line": 961,
          "quote": "A **Prime semantic atom** is one irreducible design relation: an atomic function\nfamily, identity, authority transition, lifecycle relation, topology, effect,\nclosure law, or composition law that cannot be expressed honestly by composing\nother accepted atoms while preserving the same meaning.",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/DESIGN_MODULE_METHOD.md#Design%20Module%20Method%2F4B.%20Ontology-First%20Design%20Rule%2FPrime%20Semantic%20Atoms%20And%20Universal%20Domain",
