          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/DESIGN_MODULE_METHOD.md#Design%20Module%20Method%2F4B.%20Ontology-First%20Design%20Rule%2FAuthority%20Model",
